UML:TaggedValue.value:
competentAuthority.role shall be "authority"

/*The role attribute of the competentAuthority shall take the value &ldquo;authority&rdquo;.*/
inv: competentAuthority.role = RelatedPartyRoleValue::authority

geometryIsSurface
/* Lake geometry must be a surface */
inv: self->count(geometry)=1 and self.geometry.oclIsTypeOf(GM_Surface)

geometryIsCurve
/* River geometry must be a curve */
inv: self->count(geometry)=1 and self.geometry.oclIsTypeOf(GM_Curve)

geometryIsSurface
/* Coastal water geometry must be a surface */
inv: self->count(geometry)=1 and self.geometry.oclIsTypeOf(GM_Surface)

geometryIsSurface
/* Transitional water geometry must be a surface */
inv: self->count(geometry)=1 and self.geometry.oclIsTypeOf(GM_Surface)

mainAndLargeNotForCanals
/* Main and large attributes may not be specified for canals */
inv: if ((self.artificial = True) or (self.heavilyModified = True)) then ((self->count(main)=0) and (self->count(large)=0))

/* If observation(s) are attached to an AbstractMonitoringFeature this shall have an ObservingCapability attached to it. The ObservingCapability shall reference the same Domain, Phenomenon and ProcessUsed as the observation(s). */
inv: hasObservation-&gt;notEmpty() implies observingCapability-&gt;notEmpty() and hasObservation.OM_Observation.featureOfInterest = observingCapability.featureOfInterest and hasObservation.OM_Observation.observedProperty = observingCapability.observedProperty and
hasObservation.OM_Observation.procedure = observingCapability.procedure
